#!/usr/bin/env bash
# AboWächter: erzeugt das Android-Projekt (Trusted Web Activity) im Ordner "android".
# Wird automatisch vom GitHub-Bauauftrag ausgeführt. Nicht von Hand ändern.
set -euo pipefail
OWNER="$(echo "${GITHUB_REPOSITORY_OWNER:-example}" | tr 'A-Z' 'a-z')"
REPO="$(echo "${GITHUB_REPOSITORY:-example/example.github.io}" | cut -d/ -f2 | tr 'A-Z' 'a-z')"
HOST="${APP_HOST:-}"; URL="${APP_URL:-}"
if [ -z "$HOST" ]; then HOST="$OWNER.github.io"; fi
if [ -z "$URL" ]; then
  if [ "$REPO" = "$HOST" ]; then URL="https://$HOST/"; else URL="https://$HOST/$REPO/"; fi
fi
rm -rf android
mkdir -p android
base64 -d > /tmp/abowaechter-projekt.tgz <<'B64'
